"""What a command prints that someone else chose, made safe for a terminal.

A namespace, a file or folder name, a build error quoting the source, a
title from a manifest: each was written by a developer or read off the file
system, and the person running the command may not be the person who wrote
it. Printed as it is, ``ESC[2J`` clears their screen, a carriage return
writes over the line before it, a backspace rubs out what a line says, and
U+202E makes a name read as another. So every such string goes through
:func:`shown`, or :func:`shown_lines` for text of several lines, before it
is printed. ``workpeg ui serve --fake-cloud`` and the build use
these, and so does the function runner of ``workpeg project serve``
(:mod:`workpeg.listen`), so there is one rule.

The rule is the one the build has always used for a path: a string that is
all printable is shown as it is, accents and all; one that holds anything
unprintable is shown as ``ascii()`` of it, quoted, every character that is
not ASCII escaped, so what the line says is one spelling whatever the
terminal would have done with the rest.

The only escape codes the SDK itself prints are the warning colour below,
and only when the stream is a terminal (:func:`warn`).
"""
from __future__ import annotations

from typing import Iterable, TextIO

#: Bold red, and reset.
BOLD_RED = "\033[1;31m"
RESET = "\033[0m"

#: What every dev command says about the account it runs as, in the owner's
#: words: a dev page and a dev function act with the signed-in person's
#: real access.
DEVELOPMENT_ONLY = (
    "This account is for development only, not the account you use for "
    "your company.")

#: The banner of a command that serves a dev page (``serve --fake-cloud``),
#: each sentence whole on a line of its own.
DEV_PAGE = (
    DEVELOPMENT_ONLY,
    "Your browser gives this page your Workpeg session, with everything "
    "this account can reach.",
)


def shown(text: object) -> str:
    """*text* as it may be printed: as it is when every character is
    printable, ``ascii()`` of it when any is not."""
    value = str(text)
    return value if value.isprintable() else ascii(value)


def shown_lines(text: object) -> str:
    """Text of several lines, a build error say, as it may be printed: each
    line, split at ``\\n`` and nowhere else, through :func:`shown`. A
    carriage return or a vertical tab stays inside its line, and so is
    escaped with it."""
    return "\n".join(shown(line) for line in str(text).split("\n"))


def is_tty(stream: TextIO) -> bool:
    """Whether *stream* is a terminal. A stream that cannot say is not."""
    try:
        return bool(stream.isatty())
    except Exception:                                 # noqa: BLE001
        return False


def warn(lines: Iterable[str], stream: TextIO, *, first: str = "  ⚠  ",
         rest: str = "     ") -> None:
    """Print *lines*, the SDK's own words, after a blank line: in bold red
    on a terminal, and plain anywhere else, so a log or a CI capture holds
    the words without the codes. The first line carries *first* in front of
    it, the others *rest*."""
    colour = is_tty(stream)
    print(file=stream)
    for index, line in enumerate(lines):
        text = (first if index == 0 else rest) + line
        print(f"{BOLD_RED}{text}{RESET}" if colour else text, file=stream)
    stream.flush()
